begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae050000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-terms-'||n||'@example.test',now()from generate_series(1,4)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,4)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-sql:saas-terms',clock_timestamp()+interval'2 hours'from generate_series(1,4)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic terms A'),(pg_temp.id(2),'Synthetic terms B');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic terms A'),(pg_temp.id(22),pg_temp.id(2),'Synthetic terms B');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(31),pg_temp.id(21),'Synthetic A1','Etc/UTC');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(41),pg_temp.id(21),pg_temp.id(3),array['patients.read']);
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('role','owner','plan','forged-premium','paid',true))::text,true)$$;
update public.doctor_edition_policy set mode='administrative_candidate',revision=2,change_reason='Synthetic terms verification';
select is((select count(*)::integer from public.doctor_saas_terms_versions),0,'migration invents no approved or draft Doctor offer');
select is((select terms_version_id from public.doctor_saas_configuration),null::uuid,'selected commercial terms remain explicitly unconfigured');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.doctor_saas_terms_versions'::regclass),'term versions force RLS');
select ok(not has_table_privilege('authenticated','public.doctor_saas_terms_versions','INSERT'),'subscriber cannot self-approve terms');
select ok(not has_table_privilege('service_role','public.doctor_saas_configuration','UPDATE'),'service API key cannot choose commercial policy');
select ok(not has_function_privilege('anon','public.doctor_saas_terms()','EXECUTE'),'private terms projection requires verified identity');
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_saas_terms()->>'configured','false','forged browser plan does not configure an offer');
select is(public.doctor_saas_terms()->'terms','null'::jsonb,'unknown price trial and quotas stay null, not free or unlimited');
select is(public.doctor_saas_terms()->>'purchase_available','false','unconfigured offer has no purchase action');
select is(public.doctor_saas_terms()->>'live_activation','false','terms read cannot grant real-user admission');
select throws_ok($$select * from public.doctor_saas_configuration$$,'42501',null,'raw operator policy is not a browser projection');
reset role;
insert into public.doctor_saas_terms_versions(id,plan_key,version,status)values(pg_temp.id(51),'synthetic-fixture',1,'draft');
select throws_ok($$update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=2,change_reason='Synthetic draft rejection'$$,'22023','DOCTOR_SAAS_APPROVED_TERMS_REQUIRED','incomplete draft cannot be selected');
select throws_ok($$insert into public.doctor_saas_terms_versions(plan_key,version,status)values('synthetic-incomplete',1,'approved')$$,'23514',null,'NULL fields cannot pass approved completeness through SQL three-valued logic');
select throws_ok($$insert into public.doctor_saas_terms_versions(plan_key,version,status,monthly_minor)values('synthetic-overflow',1,'draft',9007199254740992)$$,'23514',null,'money must be exactly representable across the JSON boundary');
select throws_ok($$insert into public.doctor_saas_terms_versions(plan_key,version,status,trial_days)values('synthetic-negative',1,'draft',-1)$$,'23514',null,'negative trial is rejected rather than defaulted');
select throws_ok($$insert into public.doctor_saas_terms_versions(plan_key,version,status,expiry_policy)values('synthetic-loss',1,'draft','delete_history')$$,'23514',null,'expiry cannot be configured to destroy historical access');
select throws_ok($$insert into public.doctor_saas_terms_versions(plan_key,version,status,terms_document_ref)values('synthetic-url',1,'draft','https://unapproved.example.test/terms')$$,'23514',null,'public terms reference is an opaque internal version, not an arbitrary URL');
-- Synthetic illustrative values, rolled back. These are not Doctor approval.
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,yearly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)
values(pg_temp.id(52),'synthetic-fixture',2,'approved','USD',2,1234,null,0,0,false,2,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-fixture/terms-v1','SYNTHETIC_COMMERCIAL_APPROVAL','SYNTHETIC_LEGAL_APPROVAL');
select throws_ok($$update public.doctor_saas_terms_versions set monthly_minor=1 where id=pg_temp.id(52)$$,'42501','DOCTOR_SAAS_TERMS_IMMUTABLE','approved price snapshots are immutable');
select throws_ok($$delete from public.doctor_saas_terms_versions where id=pg_temp.id(51)$$,'42501','DOCTOR_SAAS_TERMS_IMMUTABLE','draft history is also append-only');
select throws_ok($$update public.doctor_saas_configuration set terms_version_id=pg_temp.id(52),change_reason='Synthetic stale CAS'$$,'40001','DOCTOR_SAAS_CONFIGURATION_CONFLICT','operator pointer uses optimistic revision');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(52),revision=2,change_reason='Synthetic selected terms fixture';
select is((select count(*)::integer from public.doctor_saas_configuration_events),2,'pointer change preserves attributed append-only history');
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_saas_terms()->>'practice_id',pg_temp.id(21)::text,'subscriber practice comes from verified ownership');
select is(public.doctor_saas_terms()->>'configuration_revision','2','projection carries current trusted configuration revision');
select is(public.doctor_saas_terms()->'terms'->>'monthly_minor','1234','projection keeps exact approved fixture amount');
select is(public.doctor_saas_terms()->'terms'->'yearly_minor','null'::jsonb,'disabled interval is not invented or copied');
select is(public.doctor_saas_terms()->'terms'->>'trial_days','0','explicit no-trial is distinct from unknown trial');
select is(public.doctor_saas_terms()->'terms'->'staff','{"kind":"limited","limit":0}'::jsonb,'explicit zero staff allowance is not unlimited');
select is(public.doctor_saas_terms()->'terms'->>'over_limit_policy','block_new_allocation','over-limit preservation behavior is explicit approved data');
select is(public.doctor_saas_terms()->>'payment_route','unconfigured','approved commercial data does not imply a merchant route');
select is(public.doctor_saas_terms()->>'purchase_available','false','commercial configuration alone cannot create a purchase');
select ok(public.doctor_saas_terms()::text not like '%SYNTHETIC_LEGAL_APPROVAL%','internal approval evidence is not exposed to subscribers');
select pg_temp.claim(2);
select is(public.doctor_saas_terms()->>'practice_id',pg_temp.id(22)::text,'another owner sees only their own subscriber identity');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_saas_terms()$$,'42501','DOCTOR_OWNER_ENROLLMENT_REQUIRED','invited staff metadata does not create a SaaS subscriber');
select pg_temp.claim(4);
select is(public.doctor_saas_terms()->'practice_id','null'::jsonb,'eligible prospective owner gets no invented practice');
reset role;
select throws_ok($$delete from public.doctor_saas_configuration$$,'42501','DOCTOR_SAAS_CONFIGURATION_REQUIRED','required operator policy cannot be removed');
select throws_ok($$truncate public.doctor_saas_configuration$$,'42501','DOCTOR_SAAS_TERMS_IMMUTABLE','policy cannot be erased through truncate');
select throws_ok($$delete from public.doctor_saas_configuration_events$$,'42501','DOCTOR_SAAS_TERMS_IMMUTABLE','configuration history cannot be erased');
update public.doctor_saas_configuration set terms_version_id=null,revision=3,change_reason='Synthetic configuration withdrawal';
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_saas_terms()->'terms','null'::jsonb,'withdrawal becomes explicitly unconfigured without deleting terms history');
reset role;
select is((select count(*)::integer from public.doctor_saas_terms_versions),2,'all historical versions are retained');
select * from finish();rollback;
